// QueryHandler is an implementation of the task.v1.Query service.
type QueryHandler interface {
	// Params returns Task parameters.
	Params(context.Context, *connect.Request[v1.QueryTaskParamsRequest]) (*connect.Response[v1.QueryTaskParamsResponse], error)
	// Task returns the composite view of one task.
	Task(context.Context, *connect.Request[v1.QueryTaskRequest]) (*connect.Response[v1.QueryTaskResponse], error)
	// TaskStage returns the stage and next-deadline projection of one task.
	TaskStage(context.Context, *connect.Request[v1.QueryTaskStageRequest]) (*connect.Response[v1.QueryTaskStageResponse], error)
	// TaskAssignment returns the Worker assignment projection of one task.
	TaskAssignment(context.Context, *connect.Request[v1.QueryTaskAssignmentRequest]) (*connect.Response[v1.QueryTaskAssignmentResponse], error)
	// AssignmentRandomness returns the frozen assignment randomness of one task.
	AssignmentRandomness(context.Context, *connect.Request[v1.QueryAssignmentRandomnessRequest]) (*connect.Response[v1.QueryAssignmentRandomnessResponse], error)
	// TaskBudget returns the authoritative per-task accounting row.
	TaskBudget(context.Context, *connect.Request[v1.QueryTaskBudgetRequest]) (*connect.Response[v1.QueryTaskBudgetResponse], error)
	// TaskBuilders returns the frozen Task Builder selection of one task. It is the
	// only read path for the per-task Builder identity that Worker INPUT/OUTPUT
	// transfer, the three-Builder fan-out, the 2-of-3 data-ready confirmation and
	// the two Builder bitmaps all address; PRUNED and post-compaction semantics are
	// frozen on QueryTaskBuildersResponse.
	// TaskBuilders executes the TaskBuilders operation.
	TaskBuilders(context.Context, *connect.Request[v1.QueryTaskBuildersRequest]) (*connect.Response[v1.QueryTaskBuildersResponse], error)
	// InferReceipt returns one task's accepted inference receipt.
	InferReceipt(context.Context, *connect.Request[v1.QueryInferReceiptRequest]) (*connect.Response[v1.QueryInferReceiptResponse], error)
	// WorkerEvidence returns one compact objective-evidence receipt.
	WorkerEvidence(context.Context, *connect.Request[v1.QueryWorkerEvidenceRequest]) (*connect.Response[v1.QueryWorkerEvidenceResponse], error)
	// VerifierCandidateWindow returns one round's frozen verifier window.
	VerifierCandidateWindow(context.Context, *connect.Request[v1.QueryVerifierCandidateWindowRequest]) (*connect.Response[v1.QueryVerifierCandidateWindowResponse], error)
	// VerifierAssignment returns one round's verifier assignment.
	VerifierAssignment(context.Context, *connect.Request[v1.QueryVerifierAssignmentRequest]) (*connect.Response[v1.QueryVerifierAssignmentResponse], error)
	// VerifyCommit returns one verifier's commit row.
	VerifyCommit(context.Context, *connect.Request[v1.QueryVerifyCommitRequest]) (*connect.Response[v1.QueryVerifyCommitResponse], error)
	// ResultReceipt returns one verifier's result credential.
	ResultReceipt(context.Context, *connect.Request[v1.QueryResultReceiptRequest]) (*connect.Response[v1.QueryResultReceiptResponse], error)
	// DataUnavailableReports pages one round's verifier reports.
	DataUnavailableReports(context.Context, *connect.Request[v1.QueryDataUnavailableReportsRequest]) (*connect.Response[v1.QueryDataUnavailableReportsResponse], error)
	// BuilderDataUnavailable returns one (task, round, builder) aggregate.
	BuilderDataUnavailable(context.Context, *connect.Request[v1.QueryBuilderDataUnavailableRequest]) (*connect.Response[v1.QueryBuilderDataUnavailableResponse], error)
	// SettlementFacts returns the retained immutable settlement facts.
	SettlementFacts(context.Context, *connect.Request[v1.QuerySettlementFactsRequest]) (*connect.Response[v1.QuerySettlementFactsResponse], error)
	// Settlement returns the sole committed settlement state and plan.
	Settlement(context.Context, *connect.Request[v1.QuerySettlementRequest]) (*connect.Response[v1.QuerySettlementResponse], error)
	// VerificationRound returns round 1 or round 2 state.
	VerificationRound(context.Context, *connect.Request[v1.QueryVerificationRoundRequest]) (*connect.Response[v1.QueryVerificationRoundResponse], error)
	// TaskGasReimbursements pages receipts by (tx_hash, item_index).
	TaskGasReimbursements(context.Context, *connect.Request[v1.QueryTaskGasReimbursementsRequest]) (*connect.Response[v1.QueryTaskGasReimbursementsResponse], error)
	// TaskFailureClass returns one task failure classification.
	TaskFailureClass(context.Context, *connect.Request[v1.QueryTaskFailureClassRequest]) (*connect.Response[v1.QueryTaskFailureClassResponse], error)
	// EvidenceCleanup returns the bounded cleanup progress of one task.
	EvidenceCleanup(context.Context, *connect.Request[v1.QueryEvidenceCleanupRequest]) (*connect.Response[v1.QueryEvidenceCleanupResponse], error)
	// EpochTaskSummary returns either the resumable fold or its retained receipt.
	EpochTaskSummary(context.Context, *connect.Request[v1.QueryEpochTaskSummaryRequest]) (*connect.Response[v1.QueryEpochTaskSummaryResponse], error)
	// Session returns one stream session.
	Session(context.Context, *connect.Request[v1.QuerySessionRequest]) (*connect.Response[v1.QuerySessionResponse], error)
	// SessionNonce returns the next nonce for one user.
	SessionNonce(context.Context, *connect.Request[v1.QuerySessionNonceRequest]) (*connect.Response[v1.QuerySessionNonceResponse], error)
	// SessionsByOwner lists active sessions for one user.
	SessionsByOwner(context.Context, *connect.Request[v1.QuerySessionsByOwnerRequest]) (*connect.Response[v1.QuerySessionsByOwnerResponse], error)
	// SessionTerminalSummary returns one collapsed session summary.
	SessionTerminalSummary(context.Context, *connect.Request[v1.QuerySessionTerminalSummaryRequest]) (*connect.Response[v1.QuerySessionTerminalSummaryResponse], error)
	// OrderSequence returns one order sequence audit row.
	OrderSequence(context.Context, *connect.Request[v1.QueryOrderSequenceRequest]) (*connect.Response[v1.QueryOrderSequenceResponse], error)
	// RoleActiveTasks lists active tasks for one worker or verifier.
	RoleActiveTasks(context.Context, *connect.Request[v1.QueryRoleActiveTasksRequest]) (*connect.Response[v1.QueryRoleActiveTasksResponse], error)
}

